-- Drop the id column
ALTER TABLE driver_vehicle DROP COLUMN id;

-- Add composite primary key
ALTER TABLE driver_vehicle ADD PRIMARY KEY (driver_id, vehicle_id);


<?php

use Illuminate\Database\Migrations\Migration;
use Illuminate\Database\Schema\Blueprint;
use Illuminate\Support\Facades\Schema;

return new class extends Migration
{
    public function up(): void
    {
        Schema::table('driver_vehicle', function (Blueprint $table) {
            $table->dropPrimary('id');
            $table->dropColumn('id');
            $table->primary(['driver_id', 'vehicle_id']);
        });
    }

    public function down(): void
    {
        Schema::table('driver_vehicle', function (Blueprint $table) {
            $table->dropPrimary(['driver_id', 'vehicle_id']);
            $table->uuid('id')->primary()->first();
        });
    }
};



